// Hand-written `rxjs` stub: enough for a response type to be unwrapped, an
// error handler to be written, and the subject a stream service fans out through.

export interface Observer<T> {
  next?: (value: T) => void;
  error?: (err: any) => void;
  complete?: () => void;
}

export declare class Observable<T> {
  subscribe(next?: ((value: T) => void) | Observer<T>): { unsubscribe(): void };
  pipe<R>(operator: (source: Observable<T>) => Observable<R>): Observable<R>;
}

export declare class Subject<T> extends Observable<T> {
  next(value: T): void;
  asObservable(): Observable<T>;
}

export declare function of<T>(value: T): Observable<T>;
export declare function throwError(factory: () => unknown): Observable<never>;
export declare function catchError<T, R>(handler: (err: any) => Observable<R>): (source: Observable<T>) => Observable<T | R>;
